  ['Quelle solution choisit-elle ?',['Marcher jusqu’au métro.','Attendre le bus sans changer d’heure.','Annuler la réunion.'],0,'Elle adopte la suggestion de son collègue.'],
  ['Pourquoi partira-t-elle à 7 h 20 ?',['Pour garder une marge avant la réunion.','Pour arriver après 9 h.','Pour éviter de marcher.'],0,'Elle veut sécuriser son arrivée.']
