function bank(t){if(t==='reading')return typeof V13_READINGS!=='undefined'?V13_READINGS:READINGS;if(t==='listening')return typeof V13_LISTENINGS!=='undefined'?V13_LISTENINGS:LISTENINGS;if(t==='writing')return typeof V13_WRITINGS!=='undefined'?V13_WRITINGS:WRITINGS;if(t==='speaking')return typeof V13_SPEAKING!=='undefined'?V13_SPEAKING:SPEAKING;return typeof V13_APPLICATION!=='undefined'?V13_APPLICATION:APPLICATION}
function parse(x){const m=String(x&&x.id||'').match(ID_RE);if(!m)return null;const type={r181:'reading',l181:'listening',w181:'writing',s181:'speaking',a181:'application'}[m[1].toLowerCase()];return{type,day:Number(m[2]),slot:Number(m[3])-1}}
function scope(type,day){return type==='listening'?day>=4&&day<=50:day>=5&&day<=50}
function category(p){const z=(p.topic+' '+p.title+' '+p.grammar).toLowerCase();if(/transport|voyage|incident|annonce|trajet|quotidien/.test(z))return'transport';if(/week-end|passé|récit|expérience|enfance/.test(z))return /enfance|imparfait/.test(z)?'past':'travel';if(/travail|études|école|candid|formation|courriel/.test(z))return'work';if(/santé|habitude/.test(z))return'health';if(/logement|réclamation/.test(z))return'housing';if(/ville|alimentation|service public/.test(z))return'city';if(/culture|personnes/.test(z))return'culture';if(/technologie|numérique/.test(z))return'technology';if(/environnement/.test(z))return'environment';if(/société|opinion|argument|débat|point de vue/.test(z))return'society';return'service'}
function scene(p,slot){return SCENES[category(p)][slot%4]}
function norm(s){return String(s||'').replace(/\s+/g,' ').trim()}
function cap(s){s=norm(s);return s?s.charAt(0).toUpperCase()+s.slice(1):s}
function studentTitle(p){const t=String(p&&p.topic||'entraînement').replace(/&/g,'et').trim();return t.toLowerCase()==='mixte'?'Entraînement mixte':cap(t)}
function topicText(p){const t=String(p&&p.topic||'entraînement').replace(/&/g,'et').trim().toLowerCase();if(t==='mixte')return'des situations variées du quotidien';if(t==='week-end')return'le week-end';if(t==='études et travail')return'les études et le travail';if(t==='vie quotidienne'||t==='quotidien')return'la vie quotidienne';return t}
function topicDisplay(p){const t=studentTitle(p);return t==='Entraînement mixte'?'Situations variées du quotidien':t}
function contextStamp(p,slot){const months=['janvier','février','mars','avril','mai','juin','septembre','octobre','novembre','décembre'],d=1+((p.day*3+slot*5)%28),month=months[(p.day+slot)%months.length],h=8+((p.day*2+slot)%11),mins=['00','15','30','45'][slot%4];if(p.day<=10)return [`Ce récit a été partagé le ${d} ${month} à ${h} h ${mins}.`,`Ce message a été envoyé le ${d} ${month} vers ${h} h ${mins}.`,`Le témoignage a été enregistré le ${d} ${month} à ${h} h ${mins}.`,`L’entretien a eu lieu le ${d} ${month} à ${h} h ${mins}.`][slot%4];return [`La confirmation doit être donnée avant le ${d} ${month} à ${h} h ${mins}.`,`Une réponse est attendue le ${d} ${month} vers ${h} h ${mins}.`,`Le prochain point d’information est prévu le ${d} ${month} à ${h} h ${mins}.`,`La situation sera réexaminée le ${d} ${month} à ${h} h ${mins}.`][slot%4]}
function outputFocus(p){if(p.day>=31)return'';const fn=String(p&&p.function||'').replace(/\s*\/\s*/g,', ');return ` Objectif : ${fn}. Réutilisez naturellement la structure grammaticale travaillée aujourd’hui.`}
function earlyReadingBody(p,m,slot){const name=NAMES[(p.day+slot)%NAMES.length],g=grammarSentence(p,m,slot,name),lead=p.day===7?`Quand ${name} était plus jeune, la vie quotidienne était différente. ${cap(m[2])}.`:p.day===8?`${name} avait prévu de ${m[1]}. La situation semblait normale au début, mais ${m[2]}.`:p.day===9?`${name} prépare les prochains jours et doit ${m[1]}. ${cap(m[2])}.`:`${name} veut raconter comment s’est passée une situation concernant « ${topicText(p)} ». ${cap(m[2])}.`;return `${lead} ${g}

${name} explique ensuite ce qui a changé. Une solution a été envisagée : ${m[3]}. Ce choix a eu une conséquence concrète : ${m[4]}. Pour que le récit soit clair, ${name} précise l’ordre des étapes, le moment où la décision a été prise et la raison principale du changement.

À la fin, ${name} résume les principaux enseignements de cette expérience. Les informations importantes ne sont pas présentées comme une liste : elles sont reliées par une chronologie, des indications de temps et des liens de cause ou de conséquence.`}
function earlyListeningScript(p,m,slot){const name=NAMES[(p.day+slot+2)%NAMES.length],g=grammarSentence(p,m,slot,name);if(slot%4===0)return `Salut, c’est ${name}. Je voulais te raconter ma journée. ${cap(m[2])}. ${g} Ensuite, j’ai dû réfléchir à une autre solution : ${m[3]}. Le résultat est clair : ${m[4]}. Au départ, je pensais pouvoir garder le programme prévu, mais j’ai dû revoir l’ordre des étapes. Je t’expliquerai les détails quand on se verra, mais au moins tu sais pourquoi mon programme a changé.`;if(slot%4===1)return `— Alors, comment s’est passée ta journée ? — Au début, tout était prévu pour ${m[1]}, mais ${m[2]}. — Qu’est-ce que tu as fait ? — J’ai choisi de ${m[3]}. ${g} — Et ça a marché ? — Oui, même si ${m[4]}. Maintenant, je sais mieux comment m’organiser la prochaine fois.`;if(slot%4===2)return `Aujourd’hui, nous écoutons le témoignage de ${name} sur le thème « ${topicText(p)} ». ${cap(m[2])}. ${g} Pour s’adapter, ${name} a retenu la solution suivante : ${m[3]}. Le détail important est le suivant : ${m[4]}. Dans son témoignage, ${name} insiste surtout sur l’ordre des événements et sur la raison qui explique la décision finale.`;return `— Pouvez-vous raconter ce qui s’est passé ? — Oui. Je devais ${m[1]}, mais ${m[2]}. ${g} — Quelle a été votre réaction ? — J’ai envisagé plusieurs possibilités et j’ai finalement décidé de ${m[3]}. — Pourquoi ? — Parce que ${m[4]}. — Et qu’est-ce que vous retenez de cette expérience ? — Qu’il vaut mieux vérifier les informations et garder une solution de remplacement.`}
function rotate(arr,k){const n=((k%arr.length)+arr.length)%arr.length;return arr.slice(n).concat(arr.slice(0,n))}
function qprov(x,n){const p=x&&x.provenance?JSON.parse(JSON.stringify(x.provenance)):{};p.traceId=String(p.traceId||x.id||'').replace(/-Q\d+$/,'')+`-Q${n}`;p.revision=3;p.pedagogyRoute=ROUTE;return p}
function mc(x,n,stem,correct,wrong1,wrong2,why,k){const opts=rotate([correct,wrong1,wrong2],k+n);return[stem,opts,opts.indexOf(correct),why,qprov(x,n)]}
function grammarSentence(p,m,slot,nameOverride){const g=String(p.grammar||'').toLowerCase(),name=nameOverride||NAMES[(p.day+slot)%NAMES.length],day=DAYS[(p.day+slot)%DAYS.length];if(/passé composé avec avoir/.test(g))return `${cap(day)}, ${name} a vérifié les informations, a appelé le service puis a confirmé sa décision par message.`;if(/passé composé avec être/.test(g))return `${name} est parti(e) plus tôt, est arrivé(e) sans retard et est rentré(e) par un autre itinéraire.`;if(/imparfait/.test(g)&&!/vs|passé composé/.test(g))return `Avant ce changement, ${name} suivait toujours la même routine et les horaires étaient plus faciles à prévoir.`;if(/passé composé vs|deux.*passé|past tenses/.test(g))return `${name} attendait encore une réponse quand le service a annoncé une modification qui a changé le programme.`;if(/futur/.test(g))return `Demain, ${name} va vérifier ce point : ${m[4]}. La semaine prochaine, ${name} comparera les résultats avant de modifier son organisation.`;if(/cod|coi/.test(g))return `Le conseiller reçoit les documents, les vérifie, puis lui explique la prochaine étape sans répéter toutes les informations.`;if(/y \/ en|y \/ en|y.*en/.test(g))return `${name} va régulièrement à ${m[0]}; il ou elle y vérifie les informations utiles et en conserve une copie pour la suite.`;if(/qui \/ que \/ où|relation/.test(g))return `${m[0]} est le lieu où ${name} obtient l’information qui lui permet de choisir la solution qu’il ou elle préfère.`;if(/compar/.test(g))return `La première option est plus simple, mais la seconde est moins risquée et parfois aussi pratique selon l’heure choisie.`;if(/conditionnel/.test(g))return `Le conseiller explique qu’on pourrait ${m[3]} et qu’il serait préférable de confirmer avant de se déplacer.`;if(/cause|conséquence/.test(g))return `Comme ${m[2]}, l’organisation doit changer; c’est pourquoi ${name} décide de ${m[3]}.`;if(/opposition|nuance/.test(g))return `La solution paraît pratique; cependant, elle présente une limite. Par exemple, ${m[4]}, ce qui oblige à nuancer le choix.`;return `${name} compare les informations et vérifie ce détail : ${m[4]}. Puis ${name} retient cette solution : ${m[3]}, parce qu’elle correspond mieux à la situation.`}
function languageQuestion(p,x,n,k){const g=String(p.grammar||'').toLowerCase();if(/depuis|pendant|fréquence/.test(g))return mc(x,n,'Quelle phrase décrit une situation commencée dans le passé et encore vraie ?','La situation continue depuis plusieurs semaines.','La situation a duré pendant une heure et est terminée.','La situation commencera dans plusieurs semaines.','« Depuis » relie un point de départ passé à une situation encore actuelle.',k);if(/passé composé avec avoir/.test(g))return mc(x,n,'Quelle action est présentée comme terminée ?','La personne a confirmé sa décision.','La personne confirme toujours sa décision chaque matin.','La personne confirmera peut-être sa décision demain.','Le passé composé présente ici une action achevée.',k);if(/passé composé avec être/.test(g))return mc(x,n,'Quelle forme convient pour raconter un déplacement terminé ?','Elle est arrivée avant midi.','Elle a arrivée avant midi.','Elle arrivait demain avant midi.','Arriver se construit avec être au passé composé.',k);if(/imparfait/.test(g)&&!/vs|passé composé/.test(g))return mc(x,n,'Quelle information sert surtout de cadre ou d’habitude passée ?','Les horaires étaient plus simples autrefois.','Le service a envoyé un message unique hier.','Le service enverra un message demain.','L’imparfait sert ici à décrire un état ou une habitude passée.',k);if(/passé composé vs|deux.*passé|past tenses/.test(g))return mc(x,n,'Quelle relation entre les deux temps est correcte ?','Une situation était en cours quand un événement a modifié le programme.','Deux événements futurs sont présentés comme certains.','Une habitude actuelle est répétée tous les jours.','L’imparfait pose le cadre et le passé composé marque l’événement.',k);if(/futur/.test(g))return mc(x,n,'Quelle phrase distingue bien un projet proche d’une projection plus lointaine ?','Demain, elle va vérifier; plus tard, elle comparera les résultats.','Hier, elle va vérifier; maintenant, elle comparait.','Depuis hier, elle vérifiera pendant demain.','Le futur proche et le futur simple peuvent exprimer des horizons différents.',k);if(/cod|coi/.test(g))return mc(x,n,'Dans « le conseiller lui explique la prochaine étape », que remplace « lui » ?','La personne qui reçoit l’explication.','Le document qui est vérifié.','La prochaine étape elle-même.','« Lui » reprend un complément introduit par à lorsqu’il s’agit d’une personne.',k);if(/y.*en/.test(g))return mc(x,n,'Dans « elle y vérifie les informations », que remplace « y » ?','Le lieu mentionné auparavant.','Une quantité de documents.','La personne qui donne le conseil.','« Y » reprend ici un lieu.',k);if(/qui|que|où|relation/.test(g))return mc(x,n,'Quel pronom relie naturellement un lieu à une action qui s’y déroule ?','où','que','lui','« Où » peut reprendre un lieu dans une proposition relative.',k);if(/compar/.test(g))return mc(x,n,'Quelle formulation établit une comparaison correcte ?','La seconde option est moins risquée que la première.','La seconde option est moins de risquée que la première.','La seconde option est aussi de risque que la première.','Moins + adjectif + que exprime une comparaison d’infériorité.',k);if(/conditionnel/.test(g))return mc(x,n,'Quelle formulation convient à une suggestion polie ?','Vous pourriez choisir un autre créneau.','Vous pouvez de choisir un autre créneau.','Vous pourriez de choisir un autre créneau.','Le conditionnel de pouvoir permet d’atténuer une suggestion.',k);if(/cause|conséquence/.test(g))return mc(x,n,'Quel connecteur introduit naturellement une conséquence ?','C’est pourquoi','Même si','Par exemple','« C’est pourquoi » introduit la conséquence d’une cause déjà donnée.',k);if(/opposition|nuance/.test(g))return mc(x,n,'Quel mot introduit une réserve ou un contraste ?','Cependant','Donc','D’abord','« Cependant » marque une opposition ou une nuance.',k);return mc(x,n,'Quelle stratégie permet de répondre avec le plus de fiabilité ?','Relier la réponse à une information précise du document.','Choisir l’option qui contient le plus de mots.','Répondre uniquement à partir du titre.','La compréhension doit s’appuyer sur des indices du document.',k)}
function readingBody(p,m,slot){const name=NAMES[(p.day+slot)%NAMES.length],g=grammarSentence(p,m,slot),fmt=slot%4;if(fmt===0)return `${cap(m[0])}. ${name} doit ${m[1]}. Or, ${m[2]}. Avant d’agir, ${name} vérifie les horaires, les conditions et les conséquences possibles. ${g}

Deux possibilités restent réalistes. La première permet de conserver l’organisation habituelle, mais elle laisse peu de marge en cas de problème. La seconde consiste à ${m[3]}. Elle demande un changement supplémentaire, mais elle réduit le risque de devoir tout modifier au dernier moment. ${cap(m[4])}.

Après avoir comparé les deux options, ${name} choisit la solution la plus sûre. La personne note l’heure, le lieu et l’étape suivante dans son téléphone, puis envoie un message à la personne concernée. Le but n’est pas seulement d’arriver à une solution, mais de pouvoir expliquer clairement pourquoi ce choix est adapté.`;if(fmt===1)return `Objet : organisation pour ${m[0]}

Bonjour,
Je dois ${m[1]}, mais ${m[2]}. J’ai donc vérifié les informations disponibles avant de vous écrire. ${g}

Je vois deux solutions possibles. Je peux garder l’organisation prévue, avec le risque d’avoir peu de temps, ou ${m[3]}. Cette seconde possibilité me paraît plus prudente, surtout parce que ${m[4]}. Pourriez-vous me confirmer que j’ai bien compris et me dire s’il existe une autre contrainte à connaître ?

Merci d’avance pour votre réponse. Dès que j’aurai la confirmation, je pourrai prévenir les autres personnes concernées et finaliser mon organisation.
Bien cordialement,
${name}`;if(fmt===2)return `Mieux décider dans une situation concernant « ${topicText(p)} »

Dans ${m[0]}, ${name} cherche à ${m[1]}. La difficulté principale est la suivante : ${m[2]}. Plutôt que de décider immédiatement, ${name} rassemble des informations concrètes sur le temps, les conditions et les solutions disponibles. ${g}

Cette vérification fait apparaître une alternative : ${m[3]}. Elle n’est pas parfaite, mais elle répond mieux à la contrainte principale. De plus, ${m[4]}. Ce détail change la comparaison entre les options, car une solution qui paraît plus simple au départ peut finalement être moins pratique.

${name} retient donc l’option qui offre le meilleur équilibre entre sécurité, temps et simplicité. Cette décision repose sur plusieurs indices du texte et non sur une seule information isolée.`;return `${name} doit choisir comment ${m[1]} dans ${m[0]}. Une première option permet de ne presque rien changer, mais ${m[2]}. Une seconde option consiste à ${m[3]}. ${g}

Pour comparer, ${name} examine trois critères : le temps nécessaire, la marge en cas d’imprévu et la facilité de l’étape suivante. Le premier choix semble plus direct; cependant, le second devient plus intéressant quand on tient compte de ce détail : ${cap(m[4])}. ${name} demande aussi l’avis d’une autre personne, qui préfère la solution la plus prévisible.

Finalement, ${name} accepte de modifier légèrement son organisation. Le choix n’est pas le plus rapide sur le papier, mais il évite une difficulté plus importante et permet de mieux respecter les contraintes de la journée.`}
function makeReading(old,p,slot){const m=scene(p,slot),name=NAMES[(p.day+slot)%NAMES.length];let text=p.day<=10?earlyReadingBody(p,m,slot):readingBody(p,m,slot);text+=`\n\n${contextStamp(p,slot)}`;if(p.day>=31)text+=`\n\nUn second point complique toutefois la décision : les personnes concernées n’accordent pas toutes la même importance au temps, au confort et au risque d’imprévu. ${name} doit donc distinguer les faits du document, les préférences exprimées et la conclusion réellement justifiée par les informations disponibles.`;const qs=[
 mc(old,1,p.day<=10?'Quel élément a modifié le déroulement prévu ?':'Quel est le problème principal à résoudre ?',cap(m[2])+'.','Le lieu va fermer définitivement.','La personne ne souhaite plus réaliser la tâche prévue.','La difficulté centrale est explicitement présentée dans le document.',p.day+slot),
 mc(old,2,p.day<=10?'Quelle solution a été choisie ou envisagée ?':`Quelle solution ${name} envisage-t-il ou envisage-t-elle ?`,cap(m[3])+'.','Ignorer les informations disponibles.','Reporter systématiquement la tâche de plusieurs mois.','Cette solution est décrite dans le document.',p.day+slot+3),
 mc(old,3,'Quel détail influence la compréhension de la situation ?',cap(m[4])+'.','Un détail sans lien avec le document.','Une information qui n’apparaît nulle part dans le document.','Ce détail permet de comprendre la décision ou la chronologie.',p.day+slot+6),
 p.day>=31?mc(old,4,'Quelle méthode permet de distinguer un fait d’une préférence dans ce document ?','Vérifier quelle information est explicitement donnée avant d’interpréter la conclusion.','Considérer toute opinion comme un fait certain.','Choisir l’idée la plus générale sans relire le texte.','Au niveau B1, il faut relier la réponse à une preuve et distinguer fait, opinion et conclusion.',p.day+slot+9):languageQuestion(p,old,4,p.day+slot+9)
 ];return{...old,title:`${studentTitle(p)} · ${p.day<=10?['récit court','message','témoignage','chronologie'][slot%4]:['situation pratique','courriel','article court','comparaison'][slot%4]}`,text,qs,provenance:provenance(old,p,'reading')}}
function listeningScript(p,m,slot){const name=NAMES[(p.day+slot+2)%NAMES.length],g=grammarSentence(p,m,slot),extra=p.day>=31?' La personne ajoute qu’elle veut d’abord vérifier les faits avant de donner son avis, car une information partielle pourrait conduire à une mauvaise décision.':'';if(slot%4===0)return `— Bonjour, je vous appelle parce que je dois ${m[1]}. — D’accord, qu’est-ce qui pose problème ? — ${cap(m[2])}. Je voudrais éviter de décider trop vite. — Vous avez une autre possibilité : ${m[3]}. — Est-ce que cela change beaucoup mon organisation ? — Pas forcément. ${cap(m[4])}. ${g} — Très bien, je vais vérifier ce dernier point et je vous confirmerai ma décision ensuite.${extra}`;if(slot%4===1)return `— ${name}, tu as finalement choisi une solution pour ${m[1]} ? — Pas encore. ${cap(m[2])}. — Pourquoi ne pas ${m[3]} ? — J’y ai pensé. Ce serait un peu moins simple, mais ${m[4]}. — Dans ce cas, je garderais une marge et je confirmerais avant de partir. — Oui, tu as raison. ${g} Je vais comparer une dernière fois les deux options, puis prévenir les personnes concernées.${extra}`;if(slot%4===2)return `Bonjour à toutes et à tous. Voici une information pratique concernant ${m[0]}. Si vous devez ${m[1]}, attention : ${m[2]}. Une solution est possible : ${m[3]}. Avant de choisir, vérifiez bien les horaires et les conditions, car ${m[4]}. ${g} Nous vous conseillons de conserver une marge de temps et de confirmer l’information avant de vous déplacer. Si votre situation est différente, contactez le service concerné pour obtenir une réponse adaptée.${extra}`;return `— Premier point de notre réunion : comment ${m[1]} ? — Le problème est le suivant : ${cap(m[2])}. — On pourrait ${m[3]}. — Oui, mais il faut aussi tenir compte de ce détail : ${cap(m[4])}. — C’est vrai. ${g} — Alors, on ne choisit pas tout de suite : on vérifie le dernier détail, puis on confirme avant la fin de la journée. — D’accord, et on explique clairement la raison du choix dans le message final.${extra}`}
function makeListening(old,p,slot){if(p.day===4){const z=DAY4_LISTENING[slot%4];const qs=z.qs.map((q,i)=>{const correct=q[1][q[2]],opts=rotate(q[1],p.day+slot+i);return[q[0],opts,opts.indexOf(correct),q[3],qprov(old,i+1)]});return{...old,title:z.title,script:z.script,qs,provenance:provenance(old,p,'listening')}}const m=scene(p,slot);let script=p.day<=10?earlyListeningScript(p,m,slot):listeningScript(p,m,slot);script+=` ${contextStamp(p,slot)}`;const qs=[
 mc(old,1,p.day<=10?'De quoi la personne parle-t-elle principalement ?':'Pourquoi cette conversation ou cette annonce a-t-elle lieu ?',p.day<=10?`D’une situation liée à « ${topicText(p)} » dont le déroulement a changé.`:`Pour aider à ${m[1]} malgré une contrainte.`,'D’un événement sans rapport avec la situation.','D’une décision déjà prise sans aucune difficulté.','Le sujet principal est présenté dès le début de l’enregistrement.',p.day+slot),
 mc(old,2,'Quelle difficulté faut-il prendre en compte ?',cap(m[2])+'.','Un changement de prix qui n’est jamais mentionné.','Une fermeture définitive de tous les services.','La contrainte est dite ou reformulée dans l’enregistrement.',p.day+slot+3),
 mc(old,3,'Quelle solution est choisie ou envisagée ?',cap(m[3])+'.','Abandonner toute démarche sans explication.','Attendre plusieurs mois sans raison précise.','La solution apparaît avant la conclusion du document.',p.day+slot+6),
 p.day>=31?mc(old,4,'Quelle attitude est la plus proche de celle du locuteur ?','Il préfère vérifier les informations avant de décider.','Il refuse d’écouter les autres possibilités.','Il considère que les détails n’ont aucune importance.','La fin du document insiste sur la vérification avant la décision.',p.day+slot+9):languageQuestion(p,old,4,p.day+slot+9)
 ];return{...old,title:`${studentTitle(p)} · ${p.day<=10?['message vocal','conversation','témoignage','interview'][slot%4]:['appel téléphonique','conversation','annonce','réunion'][slot%4]}`,script,qs,provenance:provenance(old,p,'listening')}}
function writingMin(d){if(d>=31)return 160;if(d>=23)return 150;if(d>=17)return 140;if(d>=16)return 130;if(d>=13)return 120;if(d>=10)return 110;if(d>=7)return 100;return 90}
function makeWriting(old,p,slot){const m=scene(p,slot),min=writingMin(p.day),fmt=p.day>=31?(slot%2?'article / avis argumenté':'courriel ou lettre formelle'):(slot%2?'message développé':'courriel pratique');let prompt;if(p.day<=10)prompt=slot%2===0?`Vous écrivez à un ami pour raconter une situation concernant « ${topicText(p)} ». Expliquez ce qui s’est passé, dans quel ordre, ce qui a changé et ce que vous avez décidé. Développez suffisamment les circonstances pour que le lecteur comprenne la chronologie.`:`Vous devez ${m[1]}. Rédigez un message pour expliquer votre situation, présenter la difficulté « ${m[2]} », puis indiquer la solution que vous avez choisie et pourquoi.`;else if(p.day<19)prompt=slot%2===0?`Vous écrivez à un service au sujet de « ${topicText(p)} ». Présentez votre situation, donnez deux informations précises, formulez une demande adaptée et expliquez pourquoi cette réponse est importante pour votre organisation.`:`Vous donnez votre avis sur une situation concernant « ${topicText(p)} ». Présentez votre position, développez deux raisons, donnez un exemple concret et ajoutez une réserve ou une limite avant de conclure.`;else if(p.day<31)prompt=slot%2===0?`Une difficulté survient dans ${m[0]} : ${m[2]}. Écrivez un message structuré pour expliquer les faits, leurs conséquences, proposer au moins deux solutions et demander une réponse précise.`:`Vous devez choisir entre deux solutions concernant « ${topicText(p)} ». Comparez-les selon au moins trois critères, expliquez votre préférence, reconnaissez un avantage de l’autre option et concluez par une recommandation claire.`;else prompt=slot%2===0?`Vous avez rencontré une difficulté concernant « ${topicText(p)} ». Rédigez un texte de type ${fmt} : exposez les faits de manière précise, expliquez leurs conséquences, formulez votre demande ou votre proposition, puis justifiez-la avec des arguments et un exemple. Votre texte doit être cohérent et adapté au destinataire.`:`Un débat porte sur « ${topicText(p)} ». Rédigez un ${fmt} dans lequel vous prenez clairement position. Présentez au moins deux arguments développés, un exemple concret, une objection ou une limite, puis une conclusion qui reformule votre position sans répéter exactement l’introduction.`;prompt+=outputFocus(p);if(p.day>=31)prompt+=` Contrainte de situation : ${contextStamp(p,slot)}`;return{...old,min,title:`${studentTitle(p)} · ${fmt}`,prompt,check:['consigne entièrement traitée','organisation en paragraphes','exemples ou détails concrets','connecteurs variés',`au moins ${min} mots`],provenance:provenance(old,p,'writing')}}
function makeSpeaking(old,p,slot){const m=scene(p,slot),late=p.day>=31,target=late?240:(p.day>=19?180:Math.min(150,90+(p.day-5)*4));let part,prompt;if(late){part=['Entretien dirigé','Exercice en interaction','Point de vue','Mini-simulation'][slot%4];if(slot%4===0)prompt=`Parlez de votre expérience liée à « ${topicText(p)} ». Expliquez vos habitudes, un changement récent et un projet. Répondez ensuite à deux questions de relance en développant vos réponses.`;else if(slot%4===1)prompt=`Vous êtes dans ${m[0]}. Vous devez ${m[1]}, mais ${m[2]}. L’examinateur joue le rôle de l’interlocuteur. Expliquez le problème, demandez une solution, réagissez à une proposition insuffisante et négociez un compromis.`;else if(slot%4===2)prompt=`Présentez votre point de vue sur une question liée à « ${topicText(p)} ». Organisez votre intervention : position, deux arguments, un exemple, une limite ou un contre-argument, puis conclusion. Préparez-vous à répondre à une question de l’examinateur.`;else prompt=`Vous devez aider une autre personne à décider dans la situation suivante : ${m[2]}. Reformulez les informations importantes, comparez au moins deux options, répondez à une objection et terminez par une recommandation justifiée.`}else{part='Entraînement guidé';if(slot%4===0)prompt=`Racontez ou décrivez une situation personnelle concernant « ${topicText(p)} ». Donnez le contexte, au moins trois détails précis et une conclusion. Utilisez des phrases complètes plutôt qu’une liste de mots.`;else if(slot%4===1)prompt=`Jeu de rôle : dans ${m[0]}, vous devez ${m[1]}, mais ${m[2]}. Posez des questions, vérifiez que vous avez bien compris la réponse et proposez une solution.`;else if(slot%4===2)prompt=`Expliquez à un camarade comment vous choisiriez une solution dans un situation liée à « ${topicText(p)} ». Comparez deux options, donnez deux raisons et un exemple concret.`;else prompt=`Une personne n’est pas d’accord avec votre choix concernant « ${topicText(p)} ». Présentez votre position, écoutez une objection, reformulez-la puis proposez un compromis acceptable.`}prompt+=outputFocus(p);if(p.day>=31)prompt+=` Contrainte de situation : ${contextStamp(p,slot)}`;return{...old,part,target,title:`${studentTitle(p)} · ${part}`,prompt,check:['consigne complète','phrases développées','enchaînement clair','raison ou exemple','réaction à une relance'],provenance:provenance(old,p,'speaking')}}
function makeApplication(old,p,slot){const m=scene(p,slot);if(p.day<=10){const tasks=[
 `Vous racontez à un ami une situation concernant « ${topicText(p)} ». Donnez le contexte, expliquez ce qui a changé, racontez au moins trois étapes dans l’ordre et terminez par le résultat.`,
 `Vous laissez un message vocal pour expliquer pourquoi votre programme a changé. Présentez la situation initiale, l’imprévu « ${m[2]} », puis la solution choisie : ${m[3]}.`,
 `Une personne vous demande ce qui s’est passé. Répondez en donnant des indications de temps, la cause du changement et une conséquence concrète : ${m[4]}.`,
 `Vous comparez votre organisation avant et après un changement lié à « ${topicText(p)} ». Expliquez ce que vous faisiez ou aviez prévu, ce qui s’est produit et ce que vous ferez ensuite.`
 ];for(let i=0;i<tasks.length;i++)tasks[i]+=outputFocus(p);const keys=p.day===9?['demain','vais','projet']:p.day===7?['avant','souvent','maintenant']:['d’abord','ensuite','finalement'];return{...old,topic:p.topic,title:`${studentTitle(p)} · mise en situation ${slot+1}`,task:tasks[slot%4],keys,chunks:['D’abord…','Ensuite…','Finalement…'],provenance:provenance(old,p,'application')}}const tasks=[
 `Contexte : ${cap(m[0])}. Vous devez ${m[1]}. Expliquez votre besoin, demandez deux informations précises et vérifiez la prochaine étape avant de terminer l’échange.`,
 `Un problème apparaît : ${m[2]}. Signalez les faits calmement, expliquez la conséquence pour vous et demandez une solution concrète. Si la première proposition ne convient pas, proposez une alternative.`,
 `Deux options sont possibles. Comparez-les selon le temps, la simplicité et un troisième critère utile. Recommandez une option, justifiez votre choix et reconnaissez un avantage de l’autre.`,
 `Vous devez négocier une solution dans une situation liée à « ${topicText(p)} ». Reformulez le désaccord, proposez deux compromis réalistes, réagissez à une objection et terminez par un accord précis sur la prochaine étape.`
 ];for(let i=0;i<tasks.length;i++){tasks[i]+=outputFocus(p);if(p.day>=31)tasks[i]+=` Contrainte de situation : ${contextStamp(p,i%4)}`}const keys=slot%4===0?['voudrais','information','confirmer']:slot%4===1?['problème','solution','pourriez']:slot%4===2?['plus','moins','préfère']:['propose','comprends','accord'];return{...old,topic:p.topic,title:`${studentTitle(p)} · situation ${slot+1}`,task:tasks[slot%4],keys,chunks:slot%4===0?['Je voudrais savoir…','Si je comprends bien…','Pouvez-vous me confirmer… ?']:slot%4===1?['Je vous explique le problème…','Cette solution ne me convient pas tout à fait.','Pourriez-vous plutôt… ?']:slot%4===2?['La première option est plus…','En revanche, la seconde…','Je choisirais… parce que…']:['Je comprends votre contrainte.','Je vous propose…','Est-ce que nous pouvons nous mettre d’accord sur… ?'],provenance:provenance(old,p,'application')}}
