function duplicateAudit(){const out=[],seen=new Map();for(const t of TYPES)for(const x of bank(t)){const z=parse(x);if(!z||!scope(t,z.day)||!x.provenance||x.provenance.pedagogyRoute!==ROUTE)continue;const body=norm(t==='reading'?x.text:t==='listening'?x.script:t==='application'?x.task:x.prompt);const k=t+'|'+body;if(seen.has(k))out.push([seen.get(k),x.id]);else seen.set(k,x.id)}return out}
function rewrite(){const report={changed:{},issues:[],scoped:{},grammarAudit:{days:46,status:'existing grammar bank retained; daily curriculum alignment reviewed'}};for(const t of TYPES){report.changed[t]=0;report.scoped[t]=0;for(const x of bank(t)){const z=parse(x);if(!z||z.type!==t||!scope(t,z.day))continue;report.scoped[t]++;const p=PROFILES[z.day];if(!p){report.issues.push({type:t,id:x.id,issue:'missing-profile'});continue}const next=make(t,x,p,z.slot);Object.assign(x,next);const problems=quality(t,x,p);if(problems.length)report.issues.push({type:t,id:x.id,issue:problems.join(',')});report.changed[t]++}}return report}
